const picker=document.createElement('dialog');picker.className='wk-picker';document.body.append(picker);
const previousDirty=window.STUDIO_HAS_UNSAVED_CHANGES;
window.STUDIO_HAS_UNSAVED_CHANGES=()=>dirty() || !!previousDirty?.();
const previousClose=window.STUDIO_REQUEST_CLOSE;
window.STUDIO_REQUEST_CLOSE=async()=>{if(!await flush())return false;return previousClose?previousClose():true;};
async function api(path,data){const response=await fetch(path,{method:data===undefined?'GET':'POST',headers:{'X-Studio-Token':token,...(data===undefined?{}:{'Content-Type':'application/json'})},body:data===undefined?undefined:JSON.stringify(data)});const out=await response.json();if(out.code==='save_warnings'&&window.STUDIO_SAVE_REVIEW)return STUDIO_SAVE_REVIEW.retry(out,path,data,api);if(!response.ok||out.error)throw Error(out.error||'操作没有完成');return out;}
const query=()=>'?projectId='+encodeURIComponent(W.project.id);
let snapshotCache=null;
function snapshot(){if(special())return social.snapshot();const value=W.mode==='manifest'?W.manifest:W.rows;if(snapshotCache?.value===value&&snapshotCache.mode===W.mode)return snapshotCache.text;const text=JSON.stringify(value);snapshotCache={value,mode:W.mode,text};return text;}
const dirty=()=>!host.hidden&&(special()?!!social?.dirty():['table','manifest'].includes(W.mode)&&W.saved!==snapshot());
