function readonly(){return special()?!!socialState.readOnly:W.source==='reference'||!ownProject(W.project?.id);}
function change(fn,key=null){if(readonly())throw Error(readonlyMessage());if(W.busy)throw Error('正在保存，请稍候再编辑。');const stamp=Date.now(),editKey=key?W.mode+':'+W.selected+':'+key:null;if(!editKey||W.lastEdit?.key!==editKey||stamp-W.lastEdit.time>900){W.undo.push(snapshot());if(W.undo.length>40)W.undo.shift();}W.lastEdit=editKey?{key:editKey,time:stamp}:null;W.redo=[];if(W.mode==='table'&&fixedGame()&&W.selected&&!W.rows[W.selected]){const original=currentRows()[W.selected];if(original)W.rows[W.selected]=clone(original);}try{fn();}finally{snapshotCache=null;}renderStatus();}
