 if(name==='LoveVindicateCfg')body='<h3>表白成功率提示</h3><blockquote style="color:'+(/^#[0-9a-f]{6}$/i.test(row.color)?row.color:'#ffffff')+'">'+text(row.txt)+'</blockquote>'+stats([['成功率下限',Math.round(Number(row.target)*100)+'%']]);
 else if(name==='LoveVindicateRateCfg')body='<h3>'+text(personName(row.id))+'</h3><p>表白成功率参数</p>'+stats([['好感参数',list(row.favorParms).join(' · ')],['关注属性参数',list(row.attrParms).join(' · ')]])+'<p>游戏另计经验加成，最终成功率限制在 0%—90%。</p>';
 else if(name==='LoveActionCfg')body='<h3>'+text(row.name)+'</h3>'+stats([['解锁恋爱值',row.id],['功能',row.funcId]]);
