function modulePreview(row){
 const schema=W.table.schema;if(!schema.gameplayModule)return null;
 const list=v=>Array.isArray(v)?v:[],scalar=(v,f)=>f?.range?referenceLabel(f.range.table,v):f?.choices?.find(c=>String(c.id)===String(v))?.label??String(v??'未设置');
 const fields=schema.fields.filter(f=>f.name!=='id'&&!f.advanced&&!f.inferred&&row[f.name]!==undefined),images=fields.filter(f=>f.editorType==='Image');
 let html=images.map(f=>row[f.name]?picture(row[f.name],'icon',f.label):'').join('')+'<h3>'+esc(row.name||row.title||row.big||row.answer||row.username||schema.label)+'</h3>';
 const short=fields.filter(f=>!f.multiline&&!f.type.startsWith('list<')&&f.editorType!=='Image'&&!['name','title','answer','username'].includes(f.name));
 html+='<dl>'+short.map(f=>'<dt>'+esc(f.label)+'</dt><dd>'+esc(scalar(row[f.name],f))+'</dd>').join('')+'</dl>';
 html+=fields.filter(f=>f.multiline).map(f=>'<section class="wk-preview-list"><small>'+esc(f.label)+'</small><p>'+esc(row[f.name])+'</p></section>').join('');
 for(const f of fields.filter(f=>f.type.startsWith('list<'))){const values=list(row[f.name]);let body='';
  if(f.editorType==='Condition')body='<p>'+esc(values.every(Array.isArray)?StudentAgeConditions.summary(values,commandTemplates('condition'),W.refs):'条件尚未填完')+'</p>';
  else if(f.editorType==='Effect')body=values.map(v=>'<p>'+esc(commandTemplates('effect').find(t=>matchCommand(v,t))?.label||'自定义效果：'+(Array.isArray(v)?v.join(','):String(v)))+'</p>').join('');
  else body=values.map((v,i)=>'<p><small>'+esc(f.itemLabels?.[i]||f.slotFields?.[i]?.label||String(i+1))+' · </small>'+esc(Array.isArray(v)?v.map((x,j)=>scalar(x,f.itemFields?.find(c=>c.index===j))).join(' / '):scalar(v,f))+'</p>').join('');
  html+='<section class="wk-preview-list"><strong>'+esc(f.label)+'</strong>'+body+'</section>';
 }
 if(W.table.name==='HandicraftMiniGameCfg'){
  const points=list(row.type?row.points:row.children).filter(p=>Array.isArray(p)&&Number.isFinite(Number(p[0]))&&Number.isFinite(Number(p[1]))),extent=Math.max(2,...points.flatMap(p=>p.map(v=>Math.abs(Number(v)))))+1,scale=70/extent;
  html+='<h4>拼装位置示意</h4><svg viewBox="0 0 200 180" role="img" aria-label="拼装坐标"><path d="M100 0V180M0 90H200" stroke="#60826b"/>'+points.map(p=>'<circle cx="'+(100+Number(p[0])*scale)+'" cy="'+(90-Number(p[1])*scale)+'" r="5" fill="#e8ce8e"/>').join('')+'</svg>';
 }
 return '<article class="wk-module-preview">'+html+'</article>';
}
