function giftHTML(row){const count=Math.max(row.npc?.length||0,row.talkId?.length||0,row.type?.length||0);return `<section class="wk-gift-recipients"><h3>收礼人与剧情</h3><p class="helper">一条入口适用于所有主角；两条依次对应男、女主角。移除收礼人会同时移除这一组设置。</p>${Array.from({length:count},(_,i)=>`<article class="wk-gift-recipient"><header><strong>收礼人 ${i+1}</strong><button data-gift-remove="${i}">移除此人</button></header>${fieldHTML({label:'人物',type:'int',range:{table:'PersonCfg'}},row.npc?.[i],`npc.${i}`)}${fieldHTML({label:'剧情入口',type:'list<int>',range:{table:'TalkCfg'},itemLabels:['通用 / 男主角','女主角'],visualList:true},row.talkId?.[i]||[],`talkId.${i}`)}${fieldHTML({label:'赠送方式',type:'int',choices:[{id:0,label:'消耗并交给对方'},{id:1,label:'只触发剧情，不消耗'}]},row.type?.[i]??0,`type.${i}`)}</article>`).join('')}<button data-gift-add class="primary">＋ 添加收礼人</button></section>`;}

function fieldHTML(f,value,path){f=displayField(f,path);if(W.table?.name==='GiftEvtCfg'&&path==='npc'&&giftStructured(target()))return giftHTML(target());if(W.table?.name==='KZoneCommentCfg'&&path==='roles')return `<div class="wk-field"><label>评论作者 <small>必填</small></label>${inputHTML({range:{table:'PersonCfg'},type:'int'},Array.isArray(value)?value[0]:undefined,'roles.0')}<details class="wk-reply-person"><summary>回复其他人物（可选）</summary>${inputHTML({...f,type:'array',range:{table:'PersonCfg'}},value||[],path)}</details></div>`;return `<div class="wk-field" data-field="${esc(path)}"><label>${esc(f.label||f.name)}${f.required&&!draftTable()?' <small>必填</small>':''}</label>${inputHTML(f,value,path)}${f.description?`<p class="helper">${esc(f.description)}</p>`:''}</div>`;}
