const fieldNames={ItemPref:'物品偏好',attr:'初始属性列表',grow:'属性成长列表',className:'所在班级',examRank:'考试排名',studyRank:'学习排名',focusAttrId:'重点属性',trait:'人物特质',speciality:'人物特长',personalitys:'性格数值列表',minigame:'小游戏',items:'携带物品',state:'初始状态',order:'排序',birthday:'生日（年、月、日）',gender:'性别',introduction:'人物介绍',telephone:'电话号码',nicknames:'别名',kzoneHeadId:'企鹅头像',url:'小学立绘',url2:'中学立绘',urlParm:'小学立绘位置与缩放',urlParm2:'中学立绘位置与缩放',l2d:'小学 Live2D 模型',l2d2:'中学 Live2D 模型',l2dParm:'小学模型参数',l2dParm2:'中学模型参数',bubbleParm:'小学气泡位置',bubbleParm2:'中学气泡位置',clickAudio:'点击声音',init:'初始化参数',thumbCnt:'点赞数量',visitCnt:'访问数量',state:'使用状态',type:'类型',parent:'所属动态或评论',roles:'发言者与被回复者',effect:'效果',cond:'出现条件',max:'最大值',sprite:'显示图标',color:'显示颜色',waysTxt:'获取方式',onlyValueInUI:'仅显示数值',uiType:'显示类型'};
function displayField(f,path){f={...f};if(W.table?.name==='ModFaceCfg'&&['icon','icon_xx'].includes(f.name)){f.editorType='Image';f.advanced=false;f.hidden=false;f.label=f.name==='icon'?'中学表情图片':'小学表情图片';}if(f.label===f.name&&fieldNames[f.name])f.label=fieldNames[f.name];if(W.table?.name!=='PersonCfg'&&f.name==='url')f.label=f.label==='小学立绘'?'资源图片':f.label;const n=W.table?.name;if(n==='MinigameActionCfg'&&f.name==='parms'&&Math.floor(Number(W.selected)/100)===20)f.itemLabels=['对手最短间隔（秒）','对手最长间隔（秒）','对手成功率（0～1）','失误抖动时间（秒）'];if(n==='PersonGrowCfg'){if(['focusAttrId','trait','speciality','items','state','ItemPref'].includes(f.name)){f.advanced=false;f.hidden=false;}const relations={focusAttrId:'PersonAttrCfg',trait:'TraitsCfg',speciality:'TraitsCfg',items:'ItemCfg',state:'PersonStateCfg'};if(relations[f.name]&&!f.range)f.range={table:relations[f.name],...(f.name==='focusAttrId'?{tags:[10,11,12,13]}:{})};}if(['name','title','content','desc','description','icon','url','urls','url2'].includes(f.name)){f.advanced=false;f.hidden=false;}if(n==='PersonCfg'&&['birthday','gender','introduction','nicknames','telephone','kzoneHeadId','note','clickAudio'].includes(f.name)){f.advanced=false;f.hidden=false;}if(n==='PersonCfg'&&['l2d','l2d2','l2dParm','l2dParm2','urlParm','urlParm2','bubbleParm','bubbleParm2','init'].includes(f.name))f.advanced=true;if(n==='KZoneContentCfg'&&f.name==='role')f.range={table:'PersonCfg'};if(n==='PersonCfg'&&f.name==='kzoneHeadId')f.range={table:'KZoneAvatarCfg'};if(n==='KZoneContentCfg'&&f.name==='options')f.range={table:'KZoneCommentCfg'};if(n==='KZoneCommentCfg'&&f.name==='roles')f.range={table:'PersonCfg'};return f;}
function valueType(value){return Array.isArray(value)?'array':value&&typeof value==='object'?'object':typeof value==='number'?'float':typeof value==='boolean'?'bool':'string';}
function inputHTML(f,value,path,depth=0){let p=esc(path),type=f.type||valueType(value);if(depth===2&&Array.isArray(f.itemFields)){const item=f.itemFields.find(item=>Number(item.index)===Number(path.split('.').at(-1)));if(item){f={...f,...item};type=f.type||type;}}if(!f.itemFields&&W.table?.name==='PersonGrowCfg'&&/^ItemPref\.\d+\.0$/.test(path))f={...f,range:{table:'ItemTagCfg'}};if(!f.itemFields&&W.table?.name==='PersonGrowCfg'&&/^ItemPref\.\d+\.1$/.test(path))f={...f,choices:[{id:-1,label:'不喜欢'},{id:0,label:'普通'},{id:1,label:'喜欢'},{id:2,label:'最爱'}]};if(/^(thumbs|comments)\.\d+\.0$/.test(path)&&W.table?.name?.startsWith('KZone'))f={...f,range:{table:path.startsWith('thumbs')?'PersonCfg':'KZoneCommentCfg'}};if(depth===0&&draftTable()&&type.startsWith('list<')&&value!=null&&(!Array.isArray(value)||(type.startsWith('list<list<')&&!value.every(Array.isArray))))return `<input data-draft-raw="${p}" value="${esc(typeof value==='string'?value:JSON.stringify(value))}" aria-label="${esc(f.label||f.name)}">`;const locked=path==='id'||(W.mode==='manifest'&&['metadata.packageId','metadata.id'].includes(path));if(depth===0&&typeof value!=='string'&&['Effect','Condition'].includes(f.editorType)&&(f.listDepth>=2||type.startsWith('list<list<')||(Array.isArray(value)&&value.some(Array.isArray))))return commandsHTML(f,value,path);
if(draftTable()&&typeof value==='string'&&(type.startsWith('list<')||type==='array'))return `<input data-draft-raw="${p}" value="${esc(value)}" aria-label="${esc(f.label||f.name)}">`;
if(depth===0&&f.slotFields?.length&&Array.isArray(value)){return `<div class="wk-slot-fields" style="--wk-columns:${Math.min(f.slotFields.length,3)}">${f.slotFields.map((slot,i)=>`<label>${esc(slot.label)}${inputHTML({...slot,name:f.name},value[i],path+'.'+i,1)}</label>`).join('')}${value.slice(f.slotFields.length).map((v,i)=>`<label>扩展 ${i+1}${inputHTML({type:valueType(v)},v,path+'.'+(i+f.slotFields.length),1)}</label>`).join('')}</div>`;}
if(Array.isArray(value)||type.startsWith('list<')||type==='array'){const arr=Array.isArray(value)?value:[];if(depth===1&&f.itemFields?.length){const known=new Set(f.itemFields.map(item=>Number(item.index)));return `<div class="wk-structured-pair" style="--wk-columns:${f.itemFields.length}">${f.itemFields.map(item=>`<div class="wk-field"><label>${esc(item.label||'设置')}</label>${inputHTML({...f,type:item.type||'int'},arr[item.index],path+'.'+item.index,depth+1)}</div>`).join('')}${arr.some((_,i)=>!known.has(i))?`<details class="wk-advanced"><summary>原有扩展参数</summary>${arr.map((value,i)=>known.has(i)?'':fieldHTML({name:String(i),label:'扩展参数 '+(i+1),type:valueType(value)},value,path+'.'+i)).join('')}</details>`:''}</div>`;}const subtype=type.startsWith('list<')?type.slice(5,-1):(arr.length?valueType(arr[0]):'string');if(!f.visualList&&!f.range&&!f.itemFields&&f.editorType!=='Image'&&!subtype.startsWith('list')&&!['array','object'].includes(subtype)&&!arr.some(v=>v!==null&&typeof v==='object'))return StudentAgeConditions.parameterHTML(arr,`data-parameter-raw="${p}"`,subtype);return `<div class="wk-array ${draftTable()&&depth===0&&!subtype.startsWith('list')&&!f.itemFields?'wk-array-inline':''}">${arr.map((v,i)=>`<div class="wk-array-item"><span class="wk-index">${depth===0&&f.itemLabels?.[i]?esc(f.itemLabels[i]):draftTable()&&path==='weight'&&W.table.name==='JobCfg'?(i+1)+'星':i+1}</span><div class="wk-value">${inputHTML({...f,type:type==='array'?valueType(v):subtype},v,path+'.'+i,depth+1)}</div><button class="icon-button" data-remove="${p}.${i}" title="删除此项">×</button></div>`).join('')}<button class="text-button" data-add="${p}" data-subtype="${esc(subtype)}">＋ 添加一项</button></div>`;}
if(value&&typeof value==='object')return `<div class="wk-object">${Object.entries(value).map(([k,v])=>fieldHTML({name:k,label:manifestLabel(k),type:Array.isArray(v)?'array':typeof v},v,path+'.'+k)).join('')}</div>`;
if((f.editorType==='Image'||(W.table?.name==='PersonCfg'&&/^url2?\.\d+$/.test(path)))&&(value==null||typeof value==='string'))return `<div class="wk-image-input"><input data-path="${p}" value="${esc(value)}" aria-label="图片路径"><button data-image-field="${p}">导入图片</button></div>`;
if(locked)return `<input value="${esc(value)}" readonly><small class="helper">编号由新增/复制自动分配；原有引用保持稳定。</small>`;
if(f.editorType==='Color')return `<div class="wk-color-field"><input type="color" data-path="${p}" value="${/^#[0-9a-f]{6}$/i.test(value)?esc(value):'#ffffff'}" aria-label="选择颜色"><input data-path="${p}" value="${esc(value)}" aria-label="颜色值"></div>`;
if(f.multiline)return `<textarea data-path="${p}" rows="3">${esc(value)}</textarea>`;
if(f.choices?.length)return `<select data-path="${p}" data-kind="number">${value!=null&&!f.choices.some(c=>Number(c.id)===Number(value))?`<option value="${esc(value)}" selected>原值 ${esc(value)}（请选择）</option>`:''}${f.choices.map(c=>`<option value="${c.id}" ${Number(value)===Number(c.id)?'selected':''}>${esc(c.label)}</option>`).join('')}</select>`;
if(f.range?.table)return `<button class="wk-reference" data-ref="${p}" data-ref-table="${esc(f.range.table)}" data-ref-range="${esc(JSON.stringify({...f.range,...(f.min!==undefined?{startId:Math.max(Number(f.range.startId)||0,f.min)}:{})}))}">${value===undefined?'请选择'+(f.label||'配置'):StudentAgeRecordLabels.html(value,W.refs[f.range.table]?.[String(value)]?rowLabel(W.refs[f.range.table][String(value)],f.range.table):Number(value)===0?'未设置 / 默认':'未载入的引用')} <span>选择 ▾</span></button>`;
if(type==='bool'||type==='boolean')return `<label class="wk-switch"><input data-path="${p}" data-kind="boolean" type="checkbox" ${value?'checked':''}> 启用</label>`;
if(/^(int|float|double|long|number)/.test(type)||typeof value==='number')return `<input data-path="${p}" data-kind="number" type="number" step="${/int|long/.test(type)?'1':'any'}" ${f.min!==undefined?`min="${esc(f.min)}"`:''} ${f.max!==undefined?`max="${esc(f.max)}"`:''} value="${esc(value??0)}">`;
return (String(value??'').length>90||/content|description|desc|intro|text/i.test(path))?`<textarea data-path="${p}" rows="4">${esc(value??'')}</textarea>`:`<input data-path="${p}" value="${esc(value??'')}">`;}
function commandTemplates(kind){return W.info?.commands?.[kind]||[];}
async function loadCommandReferences(kind){const revision=W.revision,needed=[...new Set(commandTemplates(kind).flatMap(t=>(t.parameters||[]).map(p=>p.range?.table).filter(Boolean)))].filter(n=>!W.refs[n]);const results=await Promise.all(needed.map(name=>api('/api/table'+query()+'&name='+encodeURIComponent(name))));if(W.revision!==revision||results.some(v=>v.revision!==revision))throw Error('读取时模组发生变化，草稿已保留，请重新打开。');for(const v of results){W.refs[v.name]=v.rows;W.refLocalIds[v.name]=v.localIds||[];}}
function matchCommand(row,template){return Array.isArray(row)&&Array.isArray(template.template)&&row.length===template.template.length&&Object.entries(template.match||{}).every(([i,v])=>row[Number(i)]===v);}
function commandsHTML(field,value,path){const kind=field.editorType==='Effect'?'effect':'condition',label=kind==='effect'?'效果':'条件',templates=commandTemplates(kind),rows=Array.isArray(value)?value:[];
return `<div class="wk-commands"><div class="condition-compact-list">${rows.map((row,i)=>`<div class="condition-compact-row"><button data-existing-${kind==='effect'?'effects':'conditions'}="${esc(path)}">${i+1}. ${esc(kind==='effect'?(templates.find(t=>matchCommand(row,t))?.label||'自定义效果：'+row.join(',')):StudentAgeConditions.summary([row],templates,W.refs))}</button><button data-remove="${esc(path+'.'+i)}" aria-label="删除${label}">×</button></div>`).join('')||`<p class="helper">未设置${label}</p>`}</div><button class="primary" data-existing-${kind==='effect'?'effects':'conditions'}="${esc(path)}">＋ 添加${label}</button></div>`;}

async function referenceData(name){const names=name.split(/\s*\/\s*/);const results=await Promise.all(names.map(n=>api('/api/table'+query()+'&name='+encodeURIComponent(n))));return {rows:Object.assign({},...results.map(r=>r.rows)),localIds:results.flatMap(r=>r.localIds||[])};}
function referenceLabel(table,value){const item=W.refs[table]?.[String(value)];return item?rowLabel(item,table)+' · '+value:(Number(value)===0?'未设置 / 默认':'编号 '+value);}
function target(){return W.mode==='manifest'?W.manifest:currentRows()[W.selected];}
function valueAt(path){return path.split('.').reduce((obj,k)=>obj?.[k],target());}
function assign(path,value){const parts=path.split('.');if(parts.some(k=>['__proto__','constructor','prototype'].includes(k)))throw Error('此扩展字段仅保留原值。');const last=parts.pop();if(W.table?.name==='GiftEvtCfg'&&['npc','talkId','type'].includes(parts[0])&&target()[parts[0]]==null)target()[parts[0]]=[];const parent=parts.reduce((obj,k)=>obj?.[k],target());if(parent==null)throw Error('字段位置已变化，请重新选择记录。');parent[last]=value;}
async function chooseReference(path,table,rangeOverride=null){if(readonly()||W.busy)return;status('正在读取可选项目…');if(!W.refs[table])W.refs[table]=(await referenceData(table)).rows;picker.innerHTML=`<h2>选择${esc(({RenshengguanTypeCfg:'人生观类型'})[table]||W.table?.schema?.fields.find(f=>f.name===path.split('.')[0])?.label?.replace(/编号|ID/g,'')||W.info.tables.find(t=>t.name===table)?.label?.replace(/[A-Za-z]+Cfg/g,'可选配置')||'配置')}</h2><input id="wk-ref-search" placeholder="按名称或编号搜索…"><div id="wk-ref-rows"></div><button id="wk-ref-cancel">取消</button>`;const rows=W.refs[table];const field=W.table?.schema?.fields.find(f=>f.name===path.split('.')[0]);const range=rangeOverride||field?.range;const commentOwner=table==='KZoneCommentCfg'&&['comments','options'].includes(path.split('.')[0])?(W.table?.name==='KZoneContentCfg'?Number(W.selected):W.table?.name==='KZoneCommentCfg'?Math.floor(Number(W.selected)/100):null):null;const allowed=id=>(!range?.filter||Number(id)===0||range.filter.values?.includes(rows[id]?.[range.filter.field]))&&(!range?.tags||Number(id)===0||range.tags.includes(Number(rows[id]?.tag)))&&(commentOwner===null||Math.floor(Number(id)/100)===commentOwner)&&(!range||range.table!==table||((!(range.startId>0)||+id>=range.startId)&&(!(range.endId>0)||+id<=range.endId)&&!range.skips?.includes(+id)));if(['PersonCfg','BgCfg'].includes(table)){const selected=W.selected,project=W.project.id,records=Object.keys(rows).filter(allowed).map(id=>({...rows[id],id:Number(id)}));if(allowed('0')&&!records.some(r=>r.id===0))records.unshift({id:0,name:'默认 / 未设置',selectionOnly:true});const chosen=await STUDIO_ASSET_PICKER.pickRecords(table==='PersonCfg'?'portrait':'background',{title:'选择'+(table==='PersonCfg'?'人物':'背景'),projectId:project,rows:records,selected:valueAt(path)});if(chosen&&W.project.id===project&&W.selected===selected){change(()=>assign(path,Number(chosen.id)));renderRows();renderForm();status('已选择，保存后应用。');}return;}$('#wk-ref-search',picker).hidden=Object.keys(rows).filter(allowed).length<10;const paint=()=>{const text=$('#wk-ref-search',picker).value.toLowerCase();const filtered=Object.keys(rows).filter(allowed).filter(id=>StudentAgeSearch.matches(text,id,rowLabel(rows[id],table))).slice(0,150);$('#wk-ref-rows',picker).classList.toggle('wk-avatar-choices',table==='KZoneAvatarCfg');$('#wk-ref-rows',picker).innerHTML=(allowed('0')&&!filtered.includes('0')?'<button data-choice-id="0">默认 / 未设置</button>':'')+filtered.map(id=>`<button data-choice-id="${id}">${table==='KZoneAvatarCfg'?`<img src="${esc(assetURL(rows[id].icon))}" alt="头像 ${esc(id)}" loading="lazy">`:''}${StudentAgeRecordLabels.html(id,rowLabel(rows[id],table))}</button>`).join('');};paint();$('#wk-ref-search',picker).oninput=paint;picker.onclick=e=>{const pick=e.target.closest('[data-choice-id]');if(pick){change(()=>assign(path,Number(pick.dataset.choiceId)));picker.close();renderRows();renderForm();status('已选择。保存后应用到模组。');}if(e.target.id==='wk-ref-cancel')picker.close();};picker.oncancel=null;picker.showModal();}
function checkCommandInputs(){if(draftTable()){
 for(const el of host.querySelectorAll('[data-draft-raw][data-draft-edited],[data-command-raw][aria-invalid="true"],[data-parameter-raw][aria-invalid="true"]')){const path=el.dataset.draftRaw||el.dataset.commandRaw||el.dataset.parameterRaw;if(path)change(()=>{let v;try{v=JSON.parse(el.value);}catch{v=el.value;}assign(path,v);});}return;
}const invalid=host.querySelector('[data-command-raw][aria-invalid="true"],[data-parameter-raw][aria-invalid="true"]');if(invalid){invalid.focus();throw Error('有指令参数未填写完整，请修正红字提示后保存。');}}
window.addEventListener('studio-assets-imported',e=>{if(W.project?.id===e.detail.projectId&&W.revision===e.detail.previousRevision){W.revision=e.detail.revision;if(W.info)W.info.revision=e.detail.revision;for(const name of Object.keys(e.detail.importDelta||{}))delete W.refs[name];renderStatus();}});
window.addEventListener('studio-premise-created',e=>{if(W.project?.id===e.detail.projectId&&W.revision===e.detail.previousRevision){W.revision=e.detail.revision;}});
window.addEventListener('studio-premises-removed',event=>{if(W.project?.id!==event.detail.projectId)return;const pairs=new Set(event.detail.pairs);window.STUDIO_STRIP_PREMISES(W.rows,pairs);snapshotCache=null;window.STUDIO_STRIP_PREMISES(W.refs,pairs);for(const kind of ['condition','effect']){const templates=W.info?.commands?.[kind];if(templates)templates.splice(0,templates.length,...templates.filter(t=>!pairs.has(Array.isArray(t.template)?Number(t.template[2])+':'+Number(t.template[3]):'')));}W.revision=event.detail.revision;W.saved=snapshot();if(W.mode==='table')renderTable();renderStatus();});
async function save(){try{checkCommandInputs();}catch(error){if(!await STUDIO_SAVE_REVIEW.confirm([error.message+' 继续将保存已生效的内容，未能解析的输入沿用上一次有效值。']))return;}if(special())return social.save();if(W.busy)throw Error('正在保存，请等待完成。');if(readonly())throw Error(readonlyMessage());if(!dirty())return;const savedSnapshot=snapshot();W.busy=true;renderStatus();try{const data=W.mode==='manifest'?await api('/api/manifest',{projectId:W.project.id,revision:W.revision,manifest:JSON.parse(savedSnapshot)}):await api('/api/table-save',{projectId:W.project.id,revision:W.revision,name:W.table.name,scope:'local',externalDialogues:W.feature==='external-dialogues',rows:JSON.parse(savedSnapshot)});W.revision=data.revision;if(W.mode==='table'&&data.rows)W.rows=clone(data.rows);for(const name of data.updatedTables||[])delete W.refs[name];W.saved=snapshot();W.undo=[];W.redo=[];W.lastEdit=null;if(W.mode==='manifest'&&data.project)W.project=data.project;if(W.mode==='table'){const latest=await api('/api/table'+query()+'&name='+encodeURIComponent(W.table.name));W.table.rows=clone(latest.rows);W.table.referenceRows=latest.referenceRows||W.table.referenceRows;W.refs[W.table.name]=clone(latest.rows);if(W.table.name==='PersonCfg'){delete W.refs.ModFaceCfg;try{W.refs.ModFaceCfg=(await api('/api/table'+query()+'&name=ModFaceCfg')).rows;}catch{}}W.table.localIds=Object.keys(W.rows);const summary=W.info.tables.find(t=>t.name===W.table.name);if(summary)summary.localCount=W.table.localIds.length;W.refs[W.table.name]={...W.refs[W.table.name],...clone(W.rows)};renderPreview();}status('已保存，修改前的文件已自动备份。');window.STUDIO_DEFER_PROJECT_REFRESH?.();}finally{W.busy=false;renderStatus();}}
async function chooseOwner(table,title,localOnly=false,accept=null){const data=await api('/api/table'+query()+'&name='+table),rows=localOnly?(data.localRows||Object.fromEntries(data.localIds.map(id=>[id,data.rows[id]]))):clone(data.rows);W.refs[table]=data.rows;if(accept)for(const id of Object.keys(rows))if(!accept(rows[id]))delete rows[id];if(!Object.keys(rows).length)throw Error(accept?(table==='KZoneCommentCfg'?'没有可加入的评论。请先编辑这条动态的评论。':'没有可选择的项目。'):localOnly?(table==='PersonCfg'?'请先在当前模组添加人物。':'请先在当前模组添加一条动态，再创建它的评论。'):'没有可选择的项目。');return new Promise(resolve=>{picker.innerHTML=`<h2>${esc(title)}</h2><input id="wk-owner-search" placeholder="搜索名称或正文…"><div id="wk-owner-rows"></div><button data-owner-cancel>取消</button>`;const paint=()=>{const q=$('#wk-owner-search',picker).value.toLowerCase();$('#wk-owner-rows',picker).innerHTML=Object.keys(rows).filter(id=>StudentAgeSearch.matches(q,rowLabel(rows[id]),id)).slice(0,150).map(id=>`<button data-owner-id="${id}">${StudentAgeRecordLabels.html(id,rowLabel(rows[id]))}</button>`).join('');};paint();$('#wk-owner-search',picker).oninput=paint;picker.onclick=e=>{const pick=e.target.closest('[data-owner-id]');if(pick){picker.close();resolve(Number(pick.dataset.ownerId));}else if(e.target.closest('[data-owner-cancel]')){picker.close();resolve(null);}};picker.oncancel=e=>{e.preventDefault();picker.close();resolve(null);};picker.showModal();});}
async function chooseExpression(personId){return new Promise(resolve=>{picker.innerHTML=`<h2>选择要添加的表情</h2><p>${esc(personName(personId))} · 默认服装</p><div class="wk-face-picker">${expressionNames.map((label,id)=>`<button data-pick-face="${id}">${label}</button>`).join('')}</div><button data-face-cancel>取消</button>`;picker.onclick=e=>{const button=e.target.closest('[data-pick-face]');if(button){picker.close();resolve({personId,faceId:Number(button.dataset.pickFace)});}else if(e.target.closest('[data-face-cancel]')){picker.close();resolve(null);}};picker.oncancel=e=>{e.preventDefault();picker.close();resolve(null);};picker.showModal();});}
async function createRecord(copy=false,source=null){let owner=W.feature==='external-dialogues'&&W.table.name==='TalkCfg'?STUDIO_IDS.allocate('EvtCfg',{}):null;if(W.table.schema.identityTable){owner=source?Number(source.id):await chooseOwner(W.table.schema.identityTable,'选择所属'+(W.table.schema.identityTable==='PersonCfg'?'人物':'物品'));if(owner===null)return;if(W.rows[owner]){W.selected=String(owner);renderTable();return;}}if(['ShopCfg','ActionEvtCfg'].includes(W.table.name)){owner=await chooseOwner(W.table.name==='ShopCfg'?'ItemCfg':'ActionCfg','选择所属内容');if(owner===null)return;}if(W.table.name==='ModFaceCfg'){const personId=W.personId||await chooseOwner('PersonCfg','选择自定义表情所属的人物',true);if(personId===null)return;owner=await chooseExpression(personId);if(owner===null)return;}if(W.table.name==='KZoneCommentCfg')owner=W.commentPost||await chooseOwner('KZoneContentCfg','选择这条评论所属的动态',true);if(W.table.name==='KZoneProfileCfg')owner=await chooseOwner('PersonCfg','选择要设置个人档的人物');if(['KZoneCommentCfg','KZoneProfileCfg'].includes(W.table.name)&&owner===null)return;newRow(copy,source,owner);}
function newRow(copy=false,source=null,owner=null){if(fixedGame()){if(!source)throw Error('请选择已有条目修改参数。');const id=String(source.id);W.source='local';if(!W.rows[id])change(()=>W.rows[id]=clone(source));W.selected=id;W.page=0;W.search='';renderTable();return;}const fields=W.table.schema.fields||[],all={...W.table.rows,...W.rows},name=W.table.name;let id=['PersonGrowCfg','KZoneProfileCfg','ModFaceCfg','ShopCfg','ActionEvtCfg'].includes(name)?0:STUDIO_IDS.allocate(name,all,owner);
 if(['ShopCfg','ActionEvtCfg'].includes(name))id=owner;
 if(name==='KZoneProfileCfg')id=owner;if(name==='ModFaceCfg')id=owner.personId*1000+owner.faceId;
 if(owner!==null&&W.table.schema.identityTable)id=owner;
 if(id>2147483647)throw Error('没有可用编号。');
 if(name==='PersonGrowCfg'){if(!W.personId)throw Error('请先在人物资料中选择当前模组的人物，再添加成长设置。');id=W.personId;}
 if(['PersonGrowCfg','KZoneProfileCfg','ModFaceCfg'].includes(name)&&W.rows[id]){W.source='local';W.selected=String(id);renderTable();status('这个人物已有设置，请在此编辑。');return;}
 const basis=source||(copy?currentRows()[W.selected]:null),row=basis?clone(basis):Object.fromEntries(fields.map(f=>[f.name,clone(f.default??(f.type?.startsWith('list<')||f.type==='array'?[]:f.type==='string'?'':f.type==='bool'?false:f.type==='object'?{}:0))]));row.id=id;if(!basis)Object.assign(row,clone(activeFeature()?.defaults?.[name]||{}));
 if(['KZoneContentCfg','KZoneCommentCfg'].includes(name)&&basis){row.comments=[];row.options=[];if(name==='KZoneCommentCfg'){row.parent=0;row.roles=Array.isArray(row.roles)?row.roles.slice(0,1):[];}}
 if(name==='ModFaceCfg'){row.name=personName(owner.personId)+' · '+expressionNames[owner.faceId];if(!basis){row.icon='';row.icon_xx='';}}
 if(name==='KZoneCommentCfg'&&!basis){row.parent=0;const author=Number(W.refs.KZoneContentCfg?.[owner]?.role);const selected=W.refs.PersonCfg?.[author]?author:Number(Object.keys(W.refs.PersonCfg||{})[0]);row.roles=Number.isFinite(selected)?[selected]:[];}
 if(!basis&&name!=='ModFaceCfg'&&typeof row.name==='string')row.name='未命名'+(activeFeature()?.label||W.table.schema.label);W.source='local';change(()=>{W.rows[id]=row;W.selected=String(id);});W.page=0;W.search='';renderTable();status(basis?(name==='PersonCfg'?'已复制人物资料。请在“成长与喜好”中检查并设置新人物。':name.startsWith('KZone')?'已复制为新内容。原动态的评论与回复未带入，请设置属于当前内容的关联。':'已复制到当前模组。修改后保存。'):'已添加，请填写名称和内容。');}
const manifestNames={title:'模组标题',description:'模组介绍',tags:'标签',dependencies:'依赖模组',version:'版本',author:'作者',metadata:'发布信息',packageId:'包标识',id:'工坊发布编号',preview:'封面',name:'名称',url:'地址',visibility:'可见性'};
