async function audio(){if(!await guard())return;W.mode='audio';W.source='local';host.classList.remove('wk-home','wk-show-nav');const data=await api('/api/audio'+query());W.revision=data.revision;$('#wk-main').innerHTML=`<div class="wk-page"><h2>声音素材</h2><p>${subscribed()?'试听此订阅模组的背景音乐、音效和配音。':'导入背景音乐、音效或配音，并注册为可选声音。'}</p><div class="wk-audio-import" ${subscribed()?'style="display:none"':''}><input id="wk-audio-file" type="file" accept="audio/*"><input id="wk-audio-name" placeholder="素材名称"><select id="wk-audio-type"><option value="1">背景音乐</option><option value="2">音效</option><option value="3">配音</option></select><button class="primary" data-wk="import-audio">导入声音</button></div><div class="wk-audios">${data.files.map(f=>`<article><strong>${esc(f.name)}</strong><audio controls preload="none" src="/api/assets${query()}&path=${encodeURIComponent(f.path)}&token=${encodeURIComponent(token)}"></audio></article>`).join('')||'<p class="helper">这个模组没有音频文件。</p>'}</div></div>`;renderStatus();}
async function importAudio(){if(readonly())throw Error('只能向自己的本地模组导入声音。');if(W.busy)throw Error('正在处理，请稍候。');const file=$('#wk-audio-file').files[0];if(!file)throw Error('请先选择声音文件。');if(file.size>48*1024*1024)throw Error('单个声音文件需小于 48 MB。');status('正在导入声音…');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});await api('/api/audio-import',{projectId:W.project.id,revision:W.revision,fileName:file.name,data,name:$('#wk-audio-name').value||file.name,type:Number($('#wk-audio-type').value)});await audio();status('声音已导入并注册，可在声音配置中选择。');window.STUDIO_DEFER_PROJECT_REFRESH?.();}
