async function resources(){if(!await guard())return;W.mode='resources';W.source='local';host.classList.remove('wk-home','wk-show-nav');$('#wk-main').innerHTML='<div class="wk-page"><h2>游戏资源与预览</h2><div id="wk-resource-state">正在读取…</div><button class="primary" data-wk="refresh-resources">重新读取游戏素材</button><p class="helper">直接从这台电脑上的游戏资源包提取背景、CG 和静态人物图。人物表情会直接从游戏模型与本模组的自定义图片中读取。</p><h3>创意工坊发布</h3><p>完成并保存后，在游戏的模组管理中打开同一个本地模组，使用发布页面上传。上传前可在游戏内工作台完整预演。</p></div>';await resourceState();renderStatus();}
async function resourceState(){clearTimeout(resourceTimer);if(W.mode!=='resources'||host.hidden)return;const data=await api('/api/resource-status');$('#wk-resource-state').innerHTML=`<div class="wk-resource-stats"><strong>${data.images||0}<span>预览图片</span></strong><strong>${data.resourceKeys||0}<span>资源索引</span></strong><strong>${data.bundles||0}<span>游戏资源包</span></strong></div><p>${esc(data.message||data.status||'资源已就绪')}</p>`;if(['running','queued'].includes(data.status))resourceTimer=setTimeout(()=>resourceState().catch(e=>status(e.message,true)),2000);}
async function action(name){
 if(name==='space-person')return openSpace(Number(W.selected));
 if(special()&&['undo','redo','delete'].includes(name))return social[name]?.();
 if(['close','story'].includes(name)){if(!await guard())return;if(W.mode==='external-dialogues'){social?.destroy();social=null;W.mode=null;}else social?.pause?.();W.busy=true;renderStatus();try{clearTimeout(resourceTimer);await window.STUDIO_REFRESH_CURRENT_PROJECT?.(true);if(name==='story'){if(typeof window.STUDIO_OPEN_EVENTS!=='function')throw Error('事件编辑尚未就绪，请重新打开工作台。');const opened=await window.STUDIO_OPEN_EVENTS();if(opened===false)return;}host.hidden=true;}finally{W.busy=false;renderStatus();}return;}
 if(name==='save')return save();
 if(name==='remove-project')return removeProject();if(name==='home')return home();if(name==='create-project'||name==='copy-project'){if(!await guard())return;window.STUDIO_NEW_PROJECT?.(name==='copy-project');return;}
 if(name==='post-comments'){const postId=Number(W.selected);if(!await guard())return;if(!W.rows[postId])throw Error('请先保存当前动态，再添加评论。');W.commentPost=postId;W.feature='comments';await loadTable('KZoneCommentCfg');W.selected=Object.keys(currentRows())[0]||null;renderTable();status('新增评论保存后会加入所属动态。可以在这里设置作者、正文和回复。');return;}
 if(name==='return-post'){const postId=W.commentPost;if(!await guard())return;W.feature='posts';await loadTable('KZoneContentCfg');W.selected=String(postId);renderTable();return;}

 if(name==='advanced'){if(!await guard())return;W.mode='advanced';W.source='local';host.classList.remove('wk-home','wk-show-nav');$('#wk-main').innerHTML='<div class="wk-page"><button class="text-button" data-wk="home">← 工坊主页</button><h2>高级配置</h2><p>以下为游戏运行时的补充配置。仍默认仅编辑当前模组内容。</p><div class="wk-advanced-tables">'+W.info.tables.filter(t=>!t.schema?.nativePage&&!['TalkCfg','OptionCfg'].includes(t.name)).map(t=>`<button data-table="${esc(t.name)}">${esc(t.label)} <small>${t.localCount} 项</small></button>`).join('')+'</div></div>';renderStatus();return;}
 if(name==='local'||name==='reference'){if(fixedGame())return;if(W.mode!=='table'||!await guard())return;W.source=name;W.undo=[];W.redo=[];W.search='';W.page=0;W.selected=null;W.selected=Object.keys(currentRows())[0]||null;renderTable();return;}
 if(name==='copy-reference'){if(W.source!=='reference'||!ownProject(W.project?.id)||W.busy)return;const row=currentRows()[W.selected];if(row)await createRecord(true,row);return;}

 if(['new','copy','delete','undo','redo','import-audio'].includes(name)&&(readonly()||W.busy))return;
 if(name==='new'||name==='copy'){if(W.mode==='table')await createRecord(name==='copy');return;}
 if(name==='delete'){if(W.mode!=='table'||!W.rows[W.selected])return;const selected=W.selected,table=W.table.name,project=W.project.id;if(!await confirmRecordDelete(rowLabel(W.rows[selected]),fixedGame()))return;if(W.selected!==selected||W.table?.name!==table||W.project?.id!==project||readonly()||W.busy)return;change(()=>delete W.rows[selected]);W.selected=null;W.selected=Object.keys(currentRows())[0]||null;renderTable();return;}
 if(name==='undo'||name==='redo'){const from=name==='undo'?W.undo:W.redo,to=name==='undo'?W.redo:W.undo;if(!from.length)return;to.push(snapshot());const snap=JSON.parse(from.pop());W.lastEdit=null;if(W.mode==='manifest'){W.manifest=snap;renderManifest();}else{W.rows=snap;if(!W.rows[W.selected])W.selected=Object.keys(W.rows)[0]||null;renderTable();}renderStatus();return;}
 if(name==='prev'||name==='next'){W.page=Math.max(0,W.page+(name==='next'?1:-1));renderRows();return;}
 if(name==='publish'){if(readonly()||!await flush())return;return STUDIO_PUBLISH.open({project:W.project,prepare:async()=>{await flush();if(window.STUDIO_HAS_UNSAVED_CHANGES?.())throw Error('还有未保存的编辑内容，请先保存再发布。');}});}
 if(name==='manifest')return manifest();if(name==='audio')return audio();if(name==='resources')return resources();if(name==='import-audio')return importAudio();if(name==='refresh-resources'){await api('/api/resource-refresh',{});return resourceState();}
}
