 if(el.dataset.existingEffects!==undefined){if(readonly()||W.busy)return;await loadCommandReferences('effect');const path=el.dataset.existingEffects,selected=await StudentAgeEffects.open({projectId:W.project.id,templates:commandTemplates('effect'),refs:W.refs,rows:valueAt(path)||[]});if(selected){change(()=>assign(path,selected));renderForm();}return;}if(el.dataset.existingConditions!==undefined){if(readonly()||W.busy)return;await loadCommandReferences('condition');const path=el.dataset.existingConditions,selected=await window.StudentAgeConditionLibrary.open({projectId:W.project.id,templates:commandTemplates('condition'),refs:W.refs,rows:valueAt(path)||[],localIds:W.refLocalIds});if(selected){change(()=>assign(path,selected));renderForm();}return;}if(el.dataset.wkGrade!==undefined){W.previewGrade=Number(el.dataset.wkGrade);renderPreview();return;}if(el.dataset.featureFavorite)return favoriteFeature(el.dataset.featureFavorite);if(el.dataset.feature)return enterFeature(el.dataset.feature);if(el.dataset.wk)return action(el.dataset.wk);if(el.dataset.table)return loadTable(el.dataset.table);
 if(el.dataset.row){if(W.feature==='minigames'&&W.info?.pluginGameIds?.includes(String(W.table.name==='MinigameActionCfg'?Math.floor(Number(el.dataset.row)/100):el.dataset.row)))return openPlugins(W.table.name==='MinigameActionCfg'?Math.floor(Number(el.dataset.row)/100):el.dataset.row);W.selected=el.dataset.row;if(W.table?.name==='PersonCfg')W.previewFace=0;W.lastEdit=null;renderRows();renderForm();return;}
 if(el.dataset.imageField!==undefined){imageTarget=el.dataset.imageField;imageInput.click();return;}if(el.dataset.ref)return chooseReference(el.dataset.ref,el.dataset.refTable,el.dataset.refRange?JSON.parse(el.dataset.refRange):null);
 if(el.dataset.commandMove){const parts=el.dataset.commandMove.split('.'),index=Number(parts.pop()),arr=valueAt(parts.join('.')),next=index+Number(el.dataset.delta);if(next<0||next>=arr.length)return;change(()=>{const current=valueAt(parts.join('.'));const [row]=current.splice(index,1);current.splice(next,0,row);});renderForm();return;}
 if(el.dataset.remove){const parts=el.dataset.remove.split('.'),i=Number(parts.pop());change(()=>valueAt(parts.join('.')).splice(i,1));renderForm();return;}
