 if(el.dataset.commandRaw!==undefined){if(el.disabled)return;const result=StudentAgeConditions.readCommandInput(el);if(!result.error){change(()=>assign(el.dataset.commandRaw,result.values),el.dataset.commandRaw);renderForm();}return;}
 if(el.id==='wk-preview-face'){W.previewFace=Number(el.value);renderPreview();return;}if(el.id==='wk-project'){const id=el.value,request=++projectSwitchSequence;el.value=W.project?.id||'';(async()=>{if(!availableProject(id))throw Error('当前模组不可用，请刷新列表。');if(!await guard()||request!==projectSwitchSequence)return;status('正在打开模组：'+availableProject(id).name+'…');const info=await api('/api/workshop?projectId='+encodeURIComponent(id));if(request!==projectSwitchSequence)return;const loaded=await window.STUDIO_SELECT_PROJECT?.(id);if(loaded===false||request!==projectSwitchSequence)return;await open(info);})().catch(e=>{if(request!==projectSwitchSequence)return;status(e.message,true);window.STUDIO_PROJECT_LOAD_ERROR?.(e);});return;}if(el.dataset.commandAdd){if(!el.value)return;const kind=el.dataset.commandKind,template=el.value==='custom'?null:commandTemplates(kind)[Number(el.value)];if(!template&&el.value!=='custom')return;change(()=>{if(!Array.isArray(valueAt(el.dataset.commandAdd)))assign(el.dataset.commandAdd,[]);valueAt(el.dataset.commandAdd).push(clone(template?template.template:[0]));});renderForm();return;}
