document.addEventListener('keydown',e=>{if(host.hidden||picker.open||e.target.closest('#json-editor'))return;const command=e.metaKey||e.ctrlKey,key=e.key.toLowerCase();let wanted=null;if(command&&key==='s')wanted='save';else if(command&&key==='z'&&!e.target.closest('input,textarea,[contenteditable=true]'))wanted=e.shiftKey?'redo':'undo';else if(command&&key==='y'&&!e.target.closest('input,textarea,[contenteditable=true]'))wanted='redo';else if(command&&key==='f'&&special()){e.preventDefault();e.stopImmediatePropagation();social.focusSearch();return;}else if(command&&key==='f'&&$('#wk-search')){e.preventDefault();e.stopImmediatePropagation();$('#wk-search').focus();return;}else if(['delete','backspace'].includes(key)&&!e.target.closest('input,textarea,select,[contenteditable=true]'))wanted='delete';if(wanted){e.preventDefault();e.stopImmediatePropagation();Promise.resolve(action(wanted)).catch(error=>status(error.message,true));}},true);
