  if(host.hidden||W.project?.id!==window.STUDIO_CURRENT_PROJECT?.()){await open();if(host.hidden)throw Error('无法打开工坊。');}
  if(state.mode==='home'){await home();const search=$('#wk-home-search');if(search&&state.homeSearch){search.value=state.homeSearch;search.dispatchEvent(new Event('input',{bubbles:true}));}}
